29	                    .digest(value.getBytes(StandardCharsets.UTF_8));
30	            StringBuilder hex = new StringBuilder(digest.length * 2);
31	            for (byte b : digest) {
32	                hex.append(String.format("%02x", b));
33	            }
34	            return hex.toString();
35	        }
36	        catch (NoSuchAlgorithmException e) {
37	            throw new IllegalStateException("SHA-256 not available", e);
